import{_ as e,o,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const S=JSON.parse('{"title":"composable vs Store","description":"推荐放在 src/composables/market/useAllMarketStates.ts ，而 不是 写成 Pinia/Vuex Store。 维度 放在 composable ( ✅ 推荐) 放在 Store ( ⛔ 此场景不划算) 职责 纯计算 + 定时调度 + 提。","frontmatter":{"title":"composable vs Store","date":"2026-08-11T00:00:00.000Z","categories":["React 系统教程"],"tags":["React","Redux","前端","教程","OneNote","核心概念与组件"],"description":"推荐放在 src/composables/market/useAllMarketStates.ts ，而 不是 写成 Pinia/Vuex Store。 维度 放在 composable ( ✅ 推荐) 放在 Store ( ⛔ 此场景不划算) 职责 纯计算 + 定时调度 + 提。","sidebarWeight":90,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/状态改变/composable vs Store.md"},"headers":[],"relativePath":"posts/React系统教程/01-核心概念与组件/composable vs Store.md","filePath":"posts/React系统教程/01-核心概念与组件/composable vs Store.md"}'),a={name:"posts/React系统教程/01-核心概念与组件/composable vs Store.md"};function l(d,t,c,i,n,p){return o(),s("div",null,[...t[0]||(t[0]=[r('<div><h1 id="composable-vs-store" tabindex="-1">composable vs Store <a class="header-anchor" href="#composable-vs-store" aria-label="Permalink to &quot;composable vs Store&quot;">​</a></h1><blockquote><p>本节目标：理解“composable vs Store”的核心思路，并能把它用于实际开发或面试表达。 <strong>推荐放在 src/composables/market/useAllMarketStates.ts ，而</strong> <strong>不是</strong> <strong>写成 Pinia/Vuex Store。</strong></p></blockquote><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>维度</strong></td><td><strong>放在 composable (****✅</strong> <strong>推荐)</strong></td><td><strong>放在 Store (****⛔</strong> <strong>此场景不划算)</strong></td></tr><tr><td>职责</td><td>纯计算 + 定时调度 + 提供只读状态</td><td>需要 mutation/action 语义；更多模板代码</td></tr><tr><td>依赖</td><td>只用 reactive / watch，无额外库</td><td>必须引入 Pinia/Vuex，同步维护 state/action</td></tr><tr><td>Devtools 需求</td><td>开闭市状态对调试意义不大</td><td>能在 Devtools 时间旅行，但价值有限</td></tr><tr><td>运行时</td><td>timerService 已确保单例；composable 内部自带“只注册一次”的 guard</td><td>Store 也能做到，但多一层包装</td></tr><tr><td>迁移灵活性</td><td>若以后想换成 WebSocket 推送，只改这一文件</td><td>Store mutation 语义会受到限制</td></tr></tbody></table><p><strong>什么时候改写成 Store 更合适？</strong></p><ul><li>需要在 Devtools 中实时查看 / 编辑 allStates</li><li>不止一个前端项目共享同一状态（微前端）</li><li>拆分权限：某些角色只能看部分 symbol，需要 Store 层做过滤</li></ul><p>若未来真的要转换，只需：</p><ol><li>把 allStates 挂到 state，</li><li>把 recalcAll、增删监听封装成 actions，</li><li>timerService 调用逻辑保持不变。</li></ol><p>在当前业务里，上述收益不明显，故保持 composable 文件最简单、最轻量。</p></div>',1)])])}const b=e(a,[["render",l]]);export{S as __pageData,b as default};
